const I18N = (() => {
  const d = {};
  if (I18N_LANG === 'en') return d;
  const col = I18N_LANG === 'el' ? 1 : I18N_LANG === 'ru' ? 2 : 0;
  for (const r of I18N_ROWS) if (r[col] && r[col] !== r[0]) d[r[0]] = r[col];     // (identical words are left out)
  return d;
})();
function T(s) { return I18N[s] || s; }
// a text with numbers or names in it: TF('{0} of {1} right', 3, 5)
function TF(s, ...a) { return T(s).replace(/\{(\d)\}/g, (m, i) => a[+i]); }

// the page: texts, tooltips, placeholders; then everything added later
const I18N_SKIP = '.CodeMirror, pre, code, textarea, script, style, kbd, .injectionDiv, .blocklyWidgetDiv, .blocklyDropDownDiv, .wtable td, .cs-list, .problist, svg text.jnum';
function i18nNode(root) {
  if (I18N_LANG === 'en' || !root) return;
  const doText = n => {
    const raw = n.nodeValue, t = raw.trim();
    if (!t || !I18N[t] || I18N[t] === t) return;              // (the same word in both languages: nothing to write, no new mutation)
    const p = n.parentElement;
    if (p && p.closest(I18N_SKIP)) return;
    n.nodeValue = raw.replace(t, I18N[t]);
  };
  const doEl = el => {
    for (const a of ['title', 'placeholder', 'aria-label']) {
      const v = el.getAttribute && el.getAttribute(a);
      if (v && I18N[v.trim()] && I18N[v.trim()] !== v.trim()) el.setAttribute(a, I18N[v.trim()]);
    }
  };
  if (root.nodeType === 3) { doText(root); return; }
  if (root.nodeType !== 1 || root.closest(I18N_SKIP)) return;
  doEl(root);
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode: n => n.nodeType === 1 && n.matches(I18N_SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
  let n;
  while ((n = w.nextNode())) n.nodeType === 3 ? doText(n) : doEl(n);
}
function i18nStart() {
  document.documentElement.lang = I18N_LANG;
  if (I18N_LANG === 'en') return;
  i18nNode(document.body);
  new MutationObserver(ms => {
    for (const m of ms) {
      if (m.type === 'childList') m.addedNodes.forEach(i18nNode);
      else if (m.type === 'characterData') i18nNode(m.target);
      else if (m.type === 'attributes') { const v = m.target.getAttribute(m.attributeName); if (v && I18N[v.trim()] && I18N[v.trim()] !== v.trim()) m.target.setAttribute(m.attributeName, I18N[v.trim()]); }
    }
  }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['title', 'placeholder'] });
}

// Blockly: the Ardzy blocks' texts and dropdowns, and the toolbox categories
function i18nBlocks(defs) {
  if (I18N_LANG === 'en') return defs;
  for (const d of defs) {
    if (d.message0) {
      let head = d.message0, tail = '';                       // (a hat adds " %3 %4" for its statement input)
      while (true) {
        if (I18N[head]) { d.message0 = I18N[head] + tail; break; }
        const m = head.match(/^(.*) (%\d+)$/);
        if (!m) break;
        head = m[1]; tail = ' ' + m[2] + tail;
      }
    }
    (d.args0 || []).forEach(a => { if (Array.isArray(a.options)) a.options = a.options.map(o => [T(o[0]), o[1]]); });
  }
  return defs;
}
function i18nToolbox(tb) {
  if (I18N_LANG !== 'en') (tb.contents || []).forEach(c => { if (c.name) c.name = T(c.name); });
  return tb;
}
